def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Top_Ten_Report_Categories.csv"
    return pd.read_csv(path)

def process(topTenCategories2024) -> pd.DataFrame:
    import pandas as pd

    df = topTenCategories2024.copy()

    # The CSV includes blank rows plus a repeated header row at index 1.
    # Standardize column names.
    df = df.rename(
        columns={
            'State: Top Ten Report Categories': 'state',
            'Unnamed: 1': 'category',
            'Unnamed: 2': 'numReports',
            'Unnamed: 3': 'percentage',
        }
    )

    # Drop blank rows and the repeated header row (where state == 'State').
    df = df[df['state'].notna()]
    df = df[df['state'].str.strip().str.lower() != 'state']

    # Clean whitespace
    for c in ['state', 'category']:
        df[c] = df[c].astype(str).str.strip()

    return df[['state', 'category', 'numReports', 'percentage']].reset_index(drop=True)
